@Component("loanAccount-subscriber")
public class LoanAccountSubscriber extends BaseSubscriber {

	public LoanAccountSubscriber() {
	}
	
    public SubscriptionQueryResult<List<LoanAccount>, LoanAccount> loanAccountSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllLoanAccountQuery(), 
                		ResponseTypes.multipleInstancesOf(LoanAccount.class),
                		ResponseTypes.instanceOf(LoanAccount.class));
    }

    public SubscriptionQueryResult<LoanAccount, LoanAccount> loanAccountSubscribe(@DestinationVariable UUID loanAccountId) {
        return queryGateway
                .subscriptionQuery(new FindLoanAccountQuery(new LoadLoanAccountFilter(loanAccountId)), 
                		ResponseTypes.instanceOf(LoanAccount.class),
                		ResponseTypes.instanceOf(LoanAccount.class));
    }





}

